import awkward as ak


class ToyReweight:
    """Custom per-event MC weight with symmetric ±5% variations."""

    name = "toy_reweight"
    has_variations = True

    @staticmethod
    def weight(events):
        """Nominal weight: LHEWeight_originalXWGTUP normalized to 1."""
        nominal = events.LHEWeight_originalXWGTUP
        return nominal / ak.mean(nominal)

    @staticmethod
    def weight_up(events):
        """Up variation: +5% around nominal."""
        nominal = events.LHEWeight_originalXWGTUP
        normalized = nominal / ak.mean(nominal)
        return normalized * 1.05

    @staticmethod
    def weight_down(events):
        """Down variation: -5% around nominal."""
        nominal = events.LHEWeight_originalXWGTUP
        normalized = nominal / ak.mean(nominal)
        return normalized * 0.95


